dslRule:
/*!id: eclipse.jdt.ui.replaceConcatenateElementsNames*/
/*!description: Replace calls to HistoryAction.concatenateElementsNames with HistoryAction.getElementLabel, as concatenateElementsNames was refactored out.*/
/*!severity: WARNING*/
org.eclipse.jdt.internal.ui.typehierarchy.HistoryAction.concatenateElementsNames($elements$, $flags$)
=>
org.eclipse.jdt.internal.ui.typehierarchy.HistoryAction.getElementLabel($elements$)
;;

beforeExample:
package org.eclipse.jdt.internal.ui.typehierarchy;

import org.eclipse.jdt.core.IJavaElement;
import org.eclipse.jdt.internal.corext.util.Messages;
import org.eclipse.jdt.ui.JavaElementLabels;

public class HistoryAction {

    private static final long ALL_DEFAULT = JavaElementLabels.ALL_DEFAULT;
    private static final long ALL_POST_QUALIFIED = JavaElementLabels.ALL_POST_QUALIFIED;

    public HistoryAction(TypeHierarchyViewPart viewPart, IJavaElement[] elements) {
        long flags = ALL_POST_QUALIFIED | ALL_DEFAULT;
        String elementName = concatenateElementsNames(elements, flags); // Target line
    }

    protected static String concatenateElementsNames(IJavaElement[] elements, long flags) {
        String result = "";
        if (elements != null && elements.length > 0) {
            int min = Math.min(2, elements.length);
            for (int i = 0; i < min; i++) {
                String elementName = JavaElementLabels.getElementLabel(elements[i], flags);
                if (i > 0)
                    result = Messages.format(TypeHierarchyMessages.HistoryAction_javaElementConcatenation, new String[] { result, elementName });
                else
                    result = elementName;
            }
            if (elements.length > 2)
                result = Messages.format(TypeHierarchyMessages.HistoryAction_javaElementConcatenationWithEllipsis, new String[] { result });
        }
        return result;
    }

    private static String getElementLabel(IJavaElement[] elements) {
        if (elements == null || elements.length == 0)
            return null;
        return "label"; // Simplified for example
    }
}

class TypeHierarchyViewPart {}
class IJavaHelpContextIds {}
class TypeHierarchyMessages {
    public static String HistoryAction_javaElementConcatenation;
    public static String HistoryAction_javaElementConcatenationWithEllipsis;
    public static String HistoryAction_inputElements_1;
    public static String HistoryAction_inputElements_2;
    public static String HistoryAction_inputElements_3;
    public static String HistoryAction_inputElements_more;
}

